detaileddescription.para:
The number of non-zero elements.

Example: slt::SparseCOOMatrix<float>mat(3,3);
mat.set(0,0,1.0f);
mat.set(1,2,2.5f);
std::cout<<"Non-zerocount:"<<mat.initialized_count()<<std::endl;

csr



A reference to the source SparseCSRMatrix object.





std::bad_alloc



If memory allocation fails during construction.



Example: slt::SparseCSRMatrix<float>csr=...;
slt::SparseCOOMatrix<float>coo(csr);

csr



A rvalue reference to a SparseCSRMatrix (must be float or double).





std::bad_alloc



if memory allocation fails. 




The conversion preserves the ordering of entries by row.

Example: slt::DenseMatrix<float>dense={
{1.0f,0.0f,2.0f},
{0.0f,3.0f,0.0f}
};
slt::SparseCSRMatrix<float>csr(dense);
slt::SparseCOOMatrix<float>coo(std::move(csr));

csr



The source SparseCSRMatrix to convert from. 




Reference to this SparseCOOMatrix.



std::bad_alloc



if memory allocation for triplets fails.



Example: slt::SparseCSRMatrix<float>csr=create_csr_matrix();
slt::SparseCOOMatrix<float>coo;
coo=csr;

Iterator to the first Triplet in the matrix.

Example: slt::SparseCOOMatrix<float>mat(3,3);
mat.set(0,1,2.5f);
mat.set(2,0,4.0f);

for(constauto&t:mat){
std::cout<<"("<<t.row<<","<<t.col<<")="<<t.value<<std::endl;
}

Example: slt::SparseCOOMatrix<float>mat(5,5);
mat.set(0,0,2.0f);
mat.finalize();

for(autoit=mat.begin();it!=mat.end();++it){
it->value*=2.0f;//scaleallnon-zerovalues
}

Iterator to one past the last Triplet.

Example: slt::SparseCOOMatrix<float>mat(3,3);
mat.set(0,1,2.5f);
mat.set(2,0,4.0f);

autoit=mat.begin();
while(it!=mat.end()){
std::cout<<"("<<it->row<<","<<it->col<<")="<<it->value<<std::endl;
++it;
}

Example: slt::SparseCOOMatrix<float>mat(3,3);
mat.set(0,0,1.0f);
mat.set(1,2,2.0f);
mat.finalize();

std::for_each(mat.begin(),mat.end(),[](auto&t){
t.value+=1.0f;//incrementallnon-zerovalues
});

Example usage: slt::SparseCOOMatrix<float>mat(5,5);
mat.set(0,0,1.0f);
mat.set(2,3,5.5f);
mat.finalize();
floatval=mat.get(2,3);//returns5.5f
